'use strict';
// Refresh mixed cached HTML/scripts before interacting with character saves.
(()=>{const release='0.31';if(document.documentElement.dataset.release===release)return;const target=new URL(location.href);if(target.searchParams.get('release')!==release){target.searchParams.set('release',release);location.replace(target.href)}})();

const SWORD_SKILLS={powerBash:{name:'Power Bash',max:10,type:'active'},slash:{name:'Slash',max:10,type:'active'},hpBoost:{name:'HP Boost',max:5,type:'passive'},defBoost:{name:'DEF Boost',max:5,type:'passive'}};
let swordSwipes=[];
function validateSwordSkills(raw){const result={powerBash:0,slash:0,hpBoost:0,defBoost:0};if(raw===undefined)return result;if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('สกิลนักดาบไม่ถูกต้อง');for(const key of Object.keys(result)){const v=raw[key]??0;if(!Number.isInteger(v)||v<0||v>SWORD_SKILLS[key].max)throw Error('ระดับ '+SWORD_SKILLS[key].name+' ไม่ถูกต้อง');result[key]=v}return result}
function swordSkillInfo(key,lv){if(key==='powerBash')return {multiplier:2.3+.2*lv,cost:8+Math.floor(lv/3),targets:1,reach:Math.max(120,jobProfile().reach)};return {multiplier:1+.1*lv,cost:6+Math.floor(lv/4),targets:4,reach:Math.max(140,jobProfile().reach)}}
function skillDescription(key,lv){if(key==='hpBoost')return 'ติดตัว · HP สูงสุด +'+(lv*8)+'%';if(key==='defBoost')return 'ติดตัว · DEF +'+(lv*3);const info=swordSkillInfo(key,Math.max(1,lv));return Math.round(info.multiplier*100)+'% ATK · '+info.targets+' เป้าหมาย · MP '+info.cost+(key==='powerBash'?' · ผลักศัตรู':'')}
let selectedSwordSkill=null;
function renderSwordSkillWindow(body){
 hideUpgradeTooltip();body.className='sword-skill-window';body.replaceChildren();
 const title=$('modalTitle');title.textContent=JOBS[player.job].name;const sp=document.createElement('strong');sp.id='swordSP';sp.textContent='SP '+player.sp;title.append(sp);
 const close=document.createElement('button');close.id='closeSkillBtn';close.className='close-skill';close.textContent='×';close.setAttribute('aria-label','ปิดหน้าสกิล');close.onclick=closeModal;body.append(close);
 const left=document.createElement('div');left.className='skill-left';const list=document.createElement('div');list.className='sword-skill-list';
 for(const [key,skill]of Object.entries(SWORD_SKILLS)){
  const lv=player.swordSkills[key],row=document.createElement('div');row.className='sword-skill-row'+(key===selectedSwordSkill?' selected':'');
  const select=document.createElement('button');select.className='skill-select';select.setAttribute('aria-label','ดู '+skill.name);select.setAttribute('aria-pressed',String(key===selectedSwordSkill));
  const name=document.createElement('strong');name.textContent=skill.name;const level=document.createElement('span');level.textContent='Lv. '+lv+' / '+skill.max;select.append(name,level);select.onclick=()=>{selectedSwordSkill=key;renderSwordSkillWindow(body);body.querySelector('[aria-label="ดู '+skill.name+'"]').focus()};
  const wrap=document.createElement('span');wrap.className='skill-upgrade-wrap';const plus=document.createElement('button');plus.className='skill-upgrade';plus.textContent='+';plus.setAttribute('aria-label','อัป '+skill.name);plus.disabled=player.sp<1||lv>=skill.max;
  wrap.onmouseenter=()=>showSkillPreview(key,wrap);wrap.onmouseleave=()=>hideUpgradeTooltip(false);plus.onfocus=()=>showSkillPreview(key,wrap);
  plus.onclick=()=>{if(player.sp<1||player.swordSkills[key]>=skill.max)return;player.sp--;player.swordSkills[key]++;save();renderSwordSkillWindow(body);updateUI()};wrap.append(plus);row.append(select,wrap);list.append(row);
 }
 left.append(list);const slots=document.createElement('div');slots.className='skill-binding-slots';
 for(const key of ['q','w','e','r']){const cell=document.createElement('label');cell.className='skill-binding-slot';const caption=document.createElement('span');caption.textContent=key.toUpperCase();const select=document.createElement('select');select.setAttribute('aria-label','สกิลช่อง '+key.toUpperCase());const empty=document.createElement('option');empty.value='';empty.textContent='ว่าง';select.append(empty);for(const [id,skill]of Object.entries(SWORD_SKILLS)){if(skill.type!=='active'||!player.swordSkills[id])continue;const option=document.createElement('option');option.value=id;option.textContent=skill.name;select.append(option)}select.value=player.skillSlots[key]||'';select.onchange=()=>{player.skillSlots[key]=select.value||null;save();updateSwordHUD()};cell.append(caption,select);slots.append(cell)}left.append(slots);body.append(left);
 if(!selectedSwordSkill)return;const right=document.createElement('div');right.className='skill-details';right.setAttribute('role','dialog');right.setAttribute('aria-label','รายละเอียดสกิล');const detailClose=document.createElement('button');detailClose.className='close-skill-detail';detailClose.textContent='×';detailClose.setAttribute('aria-label','ปิดรายละเอียดสกิล');detailClose.onclick=()=>{selectedSwordSkill=null;renderSwordSkillWindow(body)};right.append(detailClose);const key=selectedSwordSkill,skill=SWORD_SKILLS[key],lv=player.swordSkills[key];
 const descriptions={powerBash:'ฟาดศัตรูหนึ่งตัวอย่างรุนแรงและผลักศัตรูให้ถอยหลัง',slash:'ฟันกวาดศัตรูด้านหน้าได้สูงสุด 4 ตัว',hpBoost:'เพิ่ม HP สูงสุดอย่างถาวร ไม่ต้องใส่ช่องสกิล',defBoost:'เพิ่มพลังป้องกันอย่างถาวร ไม่ต้องใส่ช่องสกิล'};
 const current=document.createElement('section');current.className='skill-detail-card';const heading=document.createElement('h3');heading.textContent=skill.name+' · Lv. '+lv+' / '+skill.max;const type=document.createElement('small');type.textContent=skill.type.toUpperCase();const desc=document.createElement('p');desc.textContent=descriptions[key];const effect=document.createElement('p');effect.className='skill-effect';effect.textContent=(lv===0?'ยังไม่เรียน · Lv.1: ':'')+skillDescription(key,Math.max(1,lv));current.append(heading,type,desc,effect);right.append(current);
 if(lv>0&&lv<skill.max){const next=document.createElement('section');next.className='skill-detail-card skill-next';const heading=document.createElement('h3');heading.textContent=skill.name+' · Lv. '+(lv+1)+' / '+skill.max;const type=document.createElement('small');type.textContent=skill.type.toUpperCase();const effect=document.createElement('p');effect.className='skill-effect';effect.textContent=skillDescription(key,lv+1);const gain=document.createElement('p');gain.className='upgrade-gain';if(skill.type==='active'){const old=swordSkillInfo(key,lv),after=swordSkillInfo(key,lv+1);gain.textContent='พลังโจมตี '+Math.round(old.multiplier*100)+'% → '+Math.round(after.multiplier*100)+'% ATK'}else gain.textContent=key==='hpBoost'?'HP สูงสุด +'+lv*8+'% → +'+(lv+1)*8+'%':'DEF +'+lv*3+' → +'+(lv+1)*3;next.append(heading,type,effect,gain);right.append(next)}body.append(right);
}

function castSwordSkill(key){if(paused||screen!=='play'||run?.finished||!['powerBash','slash'].includes(key))return false;const lv=player.swordSkills?.[key]||0;if(!lv)return false;const info=swordSkillInfo(key,lv);if(player.mp<info.cost)return false;player.mp-=info.cost;player.swing=.25;const hits=monsters.filter(m=>!m.dead&&(m.x-player.x)*player.face>=-(monsterRadius(m)+8)&&(m.x-player.x)*player.face<info.reach+monsterRadius(m)&&player.y>m.y-monsterHeight(m)-15&&player.y<m.y+46).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x)).slice(0,info.targets);swordSwipes.push({x:player.x,y:player.y-20,face:player.face,reach:info.reach,life:.28,key});for(const m of hits){const landed=hitMonster(m,attackPower()*jobProfile().multiplier*info.multiplier);if(landed&&key==='powerBash'&&!m.dead)m.x=clamp(m.x+player.face*(18+lv*2)*((m.boss||m.elite) ? .5 : 1),m.low,m.high)}burst(player.x+player.face*35,player.y-20,key==='powerBash'?'#ffda91':'#d2f3bc',8);tone(key==='powerBash'?150:340,.14,'triangle');updateUI();return true}
function usePotion(kind){if(paused||screen!=='play'||run?.finished)return false;const maximum=kind==='hp'?maxHP():maxMP(),cd=kind==='hp'?'hpPotion':'mpPotion';if(player[kind]>=maximum||player.cd[cd]>0||!(player.consumables?.[cd]>0))return false;player.consumables[cd]--;const value=Math.min(maximum-player[kind],Math.ceil(maximum*.35));player[kind]+=value;player.cd[cd]=2;burst(player.x,player.y-20,kind==='hp'?'#f5a599':'#a3d3ff',12);tone(kind==='hp'?610:760,.12);save();updateUI();return true}
function updateSwordHUD(){const slots=player.skillSlots||{},learned=player.swordSkills||{};for(const key of ['q','w','e','r']){const button=$('hotbar'+key.toUpperCase());if(!button)continue;const id=slots[key],skill=id?SWORD_SKILLS[id]:null;button.disabled=!skill||!learned[id];button.title=skill?skill.name+' · Lv.'+(learned[id]||0):'ว่าง';const caption=button.querySelector('span');if(caption)caption.textContent=key.toUpperCase()+'['+(skill?skill.name:'-----')+']';const icon=button.querySelector('.hotbar-icon');if(icon)icon.textContent=id==='powerBash'?'⌁':id==='slash'?'╱':''}for(const [kind,id]of [['hp','hpPotionBtn'],['mp','mpPotionBtn']]){const cd=kind==='hp'?'hpPotion':'mpPotion',button=$(id),label=$(kind+'PotionCD');if(button){const stock=player.consumables?.[cd]??0;button.disabled=player.cd[cd]>0||stock===0;button.classList.toggle('empty-potion',stock===0);button.title='';let text=button.querySelector('.potion-kind');if(!text){text=document.createElement('b');text.className='potion-kind';button.append(text)}text.textContent=kind.toUpperCase();let count=button.querySelector('.potion-count');if(!count){count=document.createElement('strong');count.className='potion-count';button.append(count)}count.textContent=stock;button.setAttribute('aria-label','ยา '+kind.toUpperCase()+' '+(kind==='hp'?'Z':'X')+' · '+stock+' ขวด');button.onmouseenter=()=>showItemDetail(button,POTION_ITEMS[cd],stock);button.onmouseleave=()=>hideUpgradeTooltip(false)}if(label)label.textContent=player.cd[cd]>0?player.cd[cd].toFixed(1):''}}

function tickSwordSwipes(dt){for(const swipe of swordSwipes)swipe.life-=dt;swordSwipes=swordSwipes.filter(s=>s.life>0)}
function drawSwordSwipes(){for(const s of swordSwipes){ctx.save();ctx.translate(s.x,s.y);ctx.scale(s.face,1);ctx.globalAlpha=Math.min(1,s.life*5);ctx.strokeStyle=s.key==='powerBash'?'#ffe1a0':'#d2f7c4';ctx.lineWidth=s.key==='powerBash'?7:4;ctx.beginPath();for(let i=0;i<9;i++){const angle=-1.05+i*.26,x=Math.cos(angle)*s.reach*.75,y=Math.sin(angle)*36;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.restore()}}
function validateSkillSlots(raw,skills){const slots={q:null,w:null,e:null,r:null};if(raw===undefined)return slots;if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('ช่องสกิลไม่ถูกต้อง');for(const key of Object.keys(slots)){const value=raw[key]??null;if(value!==null&&(!SWORD_SKILLS[value]||SWORD_SKILLS[value].type!=='active'||!skills[value]))throw Error('สกิลในช่อง '+key+' ไม่ถูกต้อง');slots[key]=value}return slots}
function castAssignedSkill(slot){const skill=player.skillSlots?.[slot];return skill?castSwordSkill(skill):false}
window.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-skill-slot]').forEach(b=>b.onclick=()=>castAssignedSkill(b.dataset.skillSlot));if($('hpPotionBtn'))$('hpPotionBtn').onclick=()=>usePotion('hp');if($('mpPotionBtn'))$('mpPotionBtn').onclick=()=>usePotion('mp')});

const POTION_ITEMS={hpPotion:{name:'ยาเพิ่ม HP',kind:'hp',description:'ฟื้นฟู HP 35% ของ HP สูงสุด · ใช้ด้วย Z · พักการใช้ยา 2 วินาที'},mpPotion:{name:'ยาเพิ่ม MP',kind:'mp',description:'ฟื้นฟู MP 35% ของ MP สูงสุด · ใช้ด้วย X · พักการใช้ยา 2 วินาที'}};
function validateConsumables(raw){if(raw===undefined)return {hpPotion:10,mpPotion:10};if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('ข้อมูลยาไม่ถูกต้อง');const out={};for(const key of Object.keys(POTION_ITEMS)){const value=raw[key]??0;if(!Number.isInteger(value)||value<0||value>9999)throw Error('จำนวนยาไม่ถูกต้อง');out[key]=value}return out}
function showItemDetail(anchor,item,count,pinned=false){showUpgradeTooltip(anchor,item.name||item.item,[],item.description+(count!==undefined?'\nจำนวน '+count+' ขวด':''),pinned)}
